window.FIRST5 = [
 {id:"f1",title:"New stridor after extubation",intro:"A 58-year-old was extubated 30 minutes ago. Family calls you: he is 'making a whistling noise.' You enter the room.",vs:"HR 118, RR 30, SpO₂ 88% on 2 L nasal cannula, anxious, high-pitched inspiratory sound.",
  actions:[
   {id:"a1",t:"Call for help / activate rapid response",cost:20,score:3,fb:"Stridor after extubation can progress to complete obstruction. Help must be on the way early."},
   {id:"a2",t:"Sit the client upright (high-Fowler's)",cost:15,score:2,fb:"Upright position eases airflow."},
   {id:"a3",t:"Apply high-flow oxygen per protocol",cost:30,score:2,fb:"Supports oxygenation while help arrives."},
   {id:"a4",t:"Stay and continuously monitor SpO₂, work of breathing",cost:20,score:2,fb:"Reassess constantly — the airway can close quickly."},
   {id:"a5",t:"Prepare emergency airway equipment and suction at bedside",cost:40,score:2,fb:"Anticipate reintubation."},
   {id:"a6",t:"Leave to review the chart for history",cost:120,score:-2,fb:"Leaving an unstable airway is unsafe."},
   {id:"a7",t:"Give PRN lorazepam for anxiety",cost:60,score:-3,fb:"Sedation can worsen airway compromise; anxiety here is from hypoxia."},
   {id:"a8",t:"Offer sips of water to soothe the throat",cost:30,score:-2,fb:"Aspiration risk with an unstable airway."},
   {id:"a9",t:"Document the finding",cost:60,score:0,fb:"Documentation comes after the client is safe."}],
  essential:["a1","a2","a3","a4"],debrief:"Airway first. Stridor is an upper airway emergency: call for help, position upright, oxygenate, prepare for advanced airway, and never leave."},
 {id:"f2",title:"Unresponsive with suspected hypoglycemia",intro:"A 70-year-old with type 2 diabetes on insulin is found very drowsy and sweaty at 1100. Lunch hasn't arrived. IV saline lock in place.",vs:"HR 108, BP 138/84, RR 18, SpO₂ 97%, responds only to loud voice.",
  actions:[
   {id:"b1",t:"Check fingerstick glucose",cost:45,score:3,fb:"Confirms the suspected cause quickly."},
   {id:"b2",t:"Give IV dextrose or glucagon per hypoglycemia protocol",cost:45,score:3,fb:"Client can't swallow safely: parenteral treatment per protocol."},
   {id:"b3",t:"Position on side and protect the airway",cost:15,score:2,fb:"Prevents aspiration if vomiting/seizure."},
   {id:"b4",t:"Call for help / notify provider",cost:20,score:2,fb:"Escalate an altered LOC."},
   {id:"b5",t:"Recheck glucose in 15 minutes and reassess LOC",cost:30,score:2,fb:"Evaluate the response."},
   {id:"b6",t:"Give 4 oz orange juice by mouth now",cost:30,score:-3,fb:"Never give oral fluids to a client who can't protect the airway."},
   {id:"b7",t:"Give the scheduled lunchtime insulin",cost:30,score:-3,fb:"Insulin would deepen the low."},
   {id:"b8",t:"Wait for the lunch tray",cost:120,score:-2,fb:"Delay risks seizure and brain injury."}],
  essential:["b1","b2","b3","b5"],debrief:"Altered LOC + diaphoresis in a client on insulin: check glucose, treat parenterally per protocol if unable to swallow, protect the airway, and reassess in 15 minutes. If a meter isn't available, treat per protocol rather than delay."},
 {id:"f3",title:"Heavy postpartum bleeding",intro:"Thirty minutes after a vaginal birth of a 9-lb infant, the client says she feels 'a gush.' The pad and underpad are soaked.",vs:"HR 112, BP 104/66, pale, anxious.",
  actions:[
   {id:"c1",t:"Massage the fundus with the lower uterus supported",cost:30,score:3,fb:"Treats atony, the most common cause."},
   {id:"c2",t:"Call for help / activate hemorrhage protocol",cost:20,score:3,fb:"Bring team and medications."},
   {id:"c3",t:"Check the bladder; catheterize per order if distended",cost:45,score:2,fb:"A full bladder prevents contraction."},
   {id:"c4",t:"Ensure IV access and give uterotonic per order (e.g., oxytocin)",cost:45,score:2,fb:"Medication support."},
   {id:"c5",t:"Weigh pads and monitor VS frequently",cost:30,score:2,fb:"Quantify blood loss; trend vitals."},
   {id:"c6",t:"Give methylergonovine without checking BP",cost:30,score:-2,fb:"Contraindicated with hypertension; always check BP first."},
   {id:"c7",t:"Place the newborn to breast and leave to get supplies",cost:60,score:-2,fb:"Breastfeeding helps release oxytocin, but leaving a hemorrhaging client is unsafe."},
   {id:"c8",t:"Encourage her to rest and reassess in 1 hour",cost:60,score:-3,fb:"Delay can lead to shock."}],
  essential:["c1","c2","c3","c4"],debrief:"Massage, mobilize help, empty the bladder, medicate per order, and quantify loss. Tachycardia often appears before hypotension."}
];

