window.TEACHING = [
 {id:"te1",cat:"Medication administration",title:"Inhaler use (MDI with spacer)",pts:["Shake the inhaler; attach spacer","Breathe out fully, then seal lips around the mouthpiece","Press once and breathe in slowly and deeply","Hold breath about 10 seconds","Wait about 1 minute between puffs if a second is ordered","Bronchodilator before steroid; rinse mouth after steroid"],warn:["Needing the rescue inhaler more often","Can't speak in full sentences","Lips or nails bluish"],tb:"'Show me how you'll use it at home.'",q:{stem:"Which statement by the client indicates further teaching is needed?",opts:["'I'll use my steroid inhaler when I have an attack.'","'I'll rinse my mouth after the steroid inhaler.'","'I'll hold my breath for about 10 seconds.'","'I'll shake it before each use.'"],key:0,why:"Inhaled steroids are maintenance, not rescue."}},
 {id:"te2",cat:"Medication side effects and safety",title:"Anticoagulant safety",pts:["Take at the same time daily","Soft toothbrush, electric razor","Report bleeding gums, blood in urine, black stools, severe headache","Keep INR appointments (warfarin)","Ask before taking aspirin, NSAIDs, or supplements","Medical ID"],warn:["Bleeding that won't stop","Black or bloody stools","Sudden severe headache"],tb:"'Tell me three signs of bleeding you would report.'",q:{stem:"Which statement indicates further teaching is needed about warfarin?",opts:["'I'll take ibuprofen for my arthritis.'","'I'll use an electric razor.'","'I'll keep my salad intake about the same.'","'I'll tell my dentist I take warfarin.'"],key:0,why:"NSAIDs increase bleeding risk."}},
 {id:"te3",cat:"Diabetes self-management",title:"Sick-day rules",pts:["Keep taking insulin unless your provider says otherwise","Check glucose every 2–4 hours and ketones if glucose is high","Drink fluids; small amounts often","Eat easy carbohydrates if you can't eat meals","Call provider for vomiting, ketones, or glucose persistently above the provider's threshold"],warn:["Vomiting and unable to keep fluids","Moderate/large ketones","Fruity breath, rapid breathing"],tb:"'What will you do with your insulin if you have the flu?'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'If I can't eat, I'll skip my insulin.'","'I'll check my glucose more often.'","'I'll drink sugar-free fluids if my glucose is high.'","'I'll call if I can't keep fluids down.'"],key:0,why:"Illness raises glucose; skipping insulin risks DKA."}},
 {id:"te4",cat:"Cardiac disease management",title:"Heart failure at home",pts:["Weigh every morning after voiding, same scale and clothing","Report weight gain per your provider's plan (often 2–3 lb in a day or 5 lb in a week)","Limit sodium","Take medications daily even when feeling well","Sleep with extra pillows if needed and report needing more"],warn:["New shortness of breath or needing more pillows","Swelling of legs or abdomen","Fainting"],tb:"'When and how will you weigh yourself?'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'I'll weigh myself whenever I remember during the week.'","'I'll check food labels for sodium.'","'I'll call if my weight goes up quickly.'","'I'll keep taking my medicine when I feel better.'"],key:0,why:"Daily weights at the same time detect fluid retention early."}},
 {id:"te5",cat:"Respiratory disease management",title:"Home oxygen safety",pts:["No smoking or open flames near oxygen; post no-smoking signs","Keep tank upright and secured; 10 feet from heat sources","Use water-based lubricant on lips, not petroleum jelly","Don't change the flow rate unless prescribed"],warn:["Increasing drowsiness or confusion","Worsening breathlessness"],tb:"'What will you do about the candles at home?'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'I can turn my oxygen up to 6 liters when I feel short of breath.'","'No one will smoke in the house.'","'I'll use a water-based lip balm.'","'I'll keep the tank secured.'"],key:0,why:"Flow changes require a prescription; high flow can be harmful for some COPD clients."}},
 {id:"te6",cat:"Nutrition and therapeutic diets",title:"Low-potassium diet (CKD)",pts:["Limit bananas, oranges, potatoes, tomatoes, dried fruit, avocados","Avoid salt substitutes (potassium chloride)","Choose apples, berries, rice, green beans in recommended portions","Follow fluid limits"],warn:["Muscle weakness, palpitations"],tb:"'Name two foods you'll limit.'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'I'll use a salt substitute instead of salt.'","'I'll limit bananas and oranges.'","'Apples are a better fruit choice for me.'","'I'll stick to my fluid limit.'"],key:0,why:"Most salt substitutes are potassium chloride."}},
 {id:"te7",cat:"Wound and incision care",title:"Incision care after surgery",pts:["Hand hygiene before touching the incision","Keep incision clean and dry; shower per surgeon","Splint abdominal incision with a pillow when coughing","Don't soak in a tub until cleared"],warn:["Redness spreading, warmth, pus, foul odor","Fever ≥ 100.4°F","Wound edges opening"],tb:"'Tell me what signs of infection you'll watch for.'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'A little yellow-green drainage with a smell is normal.'","'I'll wash my hands before changing the dressing.'","'I'll call for a fever over 100.4°F.'","'I'll hold a pillow against my belly when I cough.'"],key:0,why:"Purulent, malodorous drainage suggests infection."}},
 {id:"te8",cat:"Mobility and fall prevention",title:"Walker and cane use",pts:["Walker: move walker forward, then the weaker leg, then the stronger leg","Cane: hold on the stronger side; move cane with the weaker leg","Remove throw rugs; night-lights","Sturdy, nonskid shoes"],warn:["Falls or near-falls","New dizziness"],tb:"'Show me how you'll walk to the bathroom.'",q:{stem:"Which statement indicates further teaching is needed about using a cane?",opts:["'I'll hold the cane on my weak side.'","'I'll move the cane together with my weak leg.'","'I'll keep the cane close to my body.'","'I'll take off my throw rugs.'"],key:0,why:"The cane goes on the stronger side."}},
 {id:"te9",cat:"Pregnancy and postpartum instructions",title:"Postpartum warning signs",pts:["Lochia should lighten over days to weeks","Perineal care: peri bottle front to back","Rest, fluids, iron-rich foods","Mood changes: report sadness lasting more than 2 weeks or thoughts of harm"],warn:["Soaking a pad in an hour, large clots","Fever, foul-smelling lochia","Severe headache, vision changes (postpartum preeclampsia)","Chest pain, shortness of breath, one swollen painful leg"],tb:"'Which bleeding would make you call right away?'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'A bad headache with spots in my vision is normal after birth.'","'I'll call if I soak a pad in an hour.'","'I'll use my peri bottle front to back.'","'I'll report sadness that lasts more than two weeks.'"],key:0,why:"Preeclampsia can occur after birth."}},
 {id:"te10",cat:"Newborn care",title:"Safe sleep and cord care",pts:["Back to sleep, firm flat surface, no pillows/bumpers/blankets","Room-share without bed-sharing","Keep the cord dry and clean; fold diaper below the cord","No tub baths until cord falls off"],warn:["Fever ≥ 100.4°F rectal in an infant under 3 months","Redness or foul drainage at the cord","Fewer wet diapers"],tb:"'Show me how you'll put the baby down to sleep.'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'I'll put a soft pillow in the crib so he's comfortable.'","'I'll lay him on his back to sleep.'","'I'll fold the diaper below the cord.'","'He'll sleep in our room in his own crib.'"],key:0,why:"Soft objects increase SIDS/suffocation risk."}},
 {id:"te11",cat:"Mental health medication and follow-up education",title:"Starting an SSRI",pts:["Takes 2–6 weeks for full effect","Don't stop suddenly","Avoid St. John's wort and other serotonergic drugs unless approved","Report worsening mood or suicidal thoughts, especially early"],warn:["Thoughts of self-harm","Agitation, fever, muscle twitching (serotonin syndrome)"],tb:"'When do you expect to notice a difference?'",q:{stem:"Which statement indicates further teaching is needed?",opts:["'If I don't feel better in a week, I'll stop taking it.'","'It may take a few weeks to work.'","'I'll tell you if I have thoughts of hurting myself.'","'I won't take St. John's wort.'"],key:0,why:"Effects take weeks; abrupt stopping causes discontinuation symptoms."}}
];

