/* Leadership & Communication questions written for this app from Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf (PDF page numbers). */
window.LEAD_QS = [
 {id:"L01",subj:"Leadership & Communication",topic:"Two-way communication",cn:"Coordinated Care",fmt:"mc",diff:"F",ask:"Interpret",comp:"cue",stem:"An SPN enters a room and says, 'I'm here to give your bath,' then begins without waiting for a reply. Which problem does this best illustrate?",opts:["One-way communication with no opportunity for client feedback","Appropriate use of a focused question","Effective assertive communication","Therapeutic silence"],key:0,rat:"One-way communication gives information without expecting feedback. The chapter notes that feedback would have let the client question, agree, or refuse. Two-way communication is safer.",why:{"1":"No question was asked.","2":"Assertiveness respects the other person's rights; the client was given no say.","3":"Silence is a deliberate technique to let the client respond."},aid:"One-way talks AT; two-way talks WITH.",principle:"Safe communication includes feedback.",takeaway:"Introduce yourself, use two identifiers, and invite feedback.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 2"},
 {id:"L02",subj:"Leadership & Communication",topic:"Types of questions",cn:"Psychosocial Integrity",fmt:"mc",diff:"F",ask:"Interpret",comp:"cue",stem:"Which nurse question is an example of a focused question?",opts:["'On a scale of 1 to 10, how would you rate your pain right now?'","'What happened to your leg?'","'How are you feeling today?'","'Tell me about your family.'"],key:0,rat:"Focused questions provide definitive information, such as a pain rating. Open-ended questions let the client answer in a meaningful way.",why:{"1":"Open-ended.","2":"Open-ended.","3":"Open-ended invitation."},aid:"Open = story. Closed = fact. Focused = number or detail.",principle:"Match the question type to the data you need.",takeaway:"Pain ratings use focused questions.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 10"},
 {id:"L03",subj:"Leadership & Communication",topic:"Barriers: false reassurance",cn:"Psychosocial Integrity",fmt:"mc",diff:"I",ask:"Intervene",comp:"intervention",stem:"A client facing a biopsy says, 'What if it's cancer?' Which response is a barrier to communication?",opts:["'Everything will be okay; try not to worry.'","'It sounds like you're frightened about the results.'","'What concerns you most right now?'","'I'll sit with you for a while.'"],key:0,rat:"False reassurance ('Everything will be okay') guarantees something the nurse can't promise and closes the conversation.",why:{"1":"Reflection of feeling is therapeutic.","2":"Open-ended exploration is therapeutic.","3":"Offering self is therapeutic."},aid:"If you can't promise it, don't say it.",principle:"Acknowledge feelings rather than dismissing them.",takeaway:"'Don't worry' answers are almost never correct on HESI.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 12"},
 {id:"L04",subj:"Leadership & Communication",topic:"Barriers: 'why' questions and advice",cn:"Psychosocial Integrity",fmt:"sata",diff:"I",ask:"Interpret",comp:"cue",stem:"Which nurse statements are barriers to therapeutic communication? Select all that apply.",opts:["'Why didn't you take your medicine?'","'If I were you, I'd move into assisted living.'","'Let's get to the bottom of this once and for all.'","'You seem upset. I'm here to listen.'","'This is just minor surgery compared with heart surgery.'"],key:[0,1,2,4],rat:"The chapter lists 'why' questions (defensive), giving advice, probing beyond what's necessary, and belittling as barriers. Acknowledging feelings and offering presence is therapeutic.",why:{"3":"Therapeutic: acknowledges feelings and offers self."},aid:"Why, Advice, Probe, Belittle — WAPB blocks.",principle:"Judge each option separately.",takeaway:"Belittling includes downplaying the client's fears.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 12"},
 {id:"L05",subj:"Leadership & Communication",topic:"SBAR: Situation",cn:"Coordinated Care",fmt:"mc",diff:"F",ask:"Clarify",comp:"scope",stem:"The LVN calls a provider about a client with new chest pain. According to SBAR, what belongs in the Situation?",opts:["Who you are, your unit, the client's name and room, and the problem (when it started, how severe)","Admitting diagnosis, allergies, and code status","What you think is going on","What you need the provider to do"],key:0,rat:"Situation (about 10 seconds) identifies you, the unit, the client, and briefly the problem. Background holds diagnosis, VS, meds, allergies, labs, and code status.",why:{"1":"Background.","2":"Assessment.","3":"Recommendation."},aid:"S = Snapshot in 10 seconds.",principle:"Lead with the bottom line.",takeaway:"Providers want the problem first.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF pp. 21–22"},
 {id:"L06",subj:"Leadership & Communication",topic:"SBAR: ordering components",cn:"Coordinated Care",fmt:"order",diff:"I",ask:"Sequence",comp:"scope",stem:"Place these statements in SBAR order.",opts:["'This is the LVN on 3 North about Ms. P in 310; her BP is 84/50 since 1400.'","'She is post-op day 1 after hip replacement, on hydromorphone PCA, allergic to penicillin, full code.'","'I'm concerned she may be bleeding or oversedated; I've collaborated with the RN.'","'Would you like to come evaluate her and order a CBC?'"],key:[0,1,2,3],rat:"Situation, Background, Assessment (what you think is going on — collaborating with the RN), Recommendation (what you need).",why:{},aid:"S-B-A-R: Snapshot, Backstory, Analysis, Request.",principle:"Structured communication reduces errors.",takeaway:"End with a specific request.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF pp. 21–22"},
 {id:"L07",subj:"Leadership & Communication",topic:"Assertive versus aggressive",cn:"Coordinated Care",fmt:"mc",diff:"I",ask:"Interpret",comp:"cue",stem:"A coworker points out an error in front of others and adds, 'Where did you say you graduated from?' How is this behavior classified?",opts:["Aggressive — attempting to humiliate as a way of controlling","Assertive — honest feedback","Passive — avoiding conflict","Therapeutic — clarifying"],key:0,rat:"The chapter gives this exact example of aggressive behavior: an attack on the person intended to humiliate.",why:{"1":"Assertiveness doesn't violate others' rights.","2":"Passive behavior avoids expressing needs.","3":"Not client communication."},aid:"Aggressive attacks the person; assertive addresses the behavior.",principle:"Classify by intent and effect on the other person's rights.",takeaway:"Assertiveness is a tool, not a weapon.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF pp. 33–35"},
 {id:"L08",subj:"Leadership & Communication",topic:"I-messages",cn:"Coordinated Care",fmt:"mc",diff:"F",ask:"Intervene",comp:"intervention",stem:"The LVN charge nurse is frustrated that call lights aren't answered promptly. Which statement is the best example of an I-message?",opts:["'I'm trying to understand why call lights aren't being answered on time. Can you help me understand what's happening?'","'You make me want to scream when you ignore call lights.'","'Everyone on this shift is lazy.'","'Just answer the lights or I'll report you.'"],key:0,rat:"The chapter contrasts the 'you make me want to scream' message with an I-message that invites problem-solving.",why:{"1":"Blaming you-message.","2":"Labeling, aggressive.","3":"Threatening."},aid:"I feel / I need / Help me understand.",principle:"Address behavior, not character.",takeaway:"I-messages reduce defensiveness.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 21"},
 {id:"L09",subj:"Leadership & Communication",topic:"Assigning versus delegating",cn:"Coordinated Care",fmt:"matrix",diff:"A",ask:"Scope",comp:"scope",stem:"For each statement, indicate whether it describes assigning tasks or delegating duties by the LP/LV charge nurse.",rows:["The task is in the nursing assistant's job description","The nursing assistant must voluntarily accept it","The nursing assistant may refuse only if unqualified","The activity comes from the LPN/LVN's job description"],cols:["Assigning tasks","Delegating duties"],key:[0,1,0,1],rat:"Table 17.1: assigned tasks are in the assistant's job description and can be refused only if the assistant feels unqualified; delegated duties come from the LPN/LVN's job description and must be voluntarily accepted.",why:{},aid:"Assign = their job. Delegate = my job, lent to you.",principle:"Work matrix rows one at a time.",takeaway:"Accountability for the right duty to the right person stays with the LPN/LVN.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF pp. 204–206"},
 {id:"L10",subj:"Leadership & Communication",topic:"Five rights of delegation",cn:"Coordinated Care",fmt:"sata",diff:"I",ask:"Scope",comp:"scope",stem:"Which are among the five rights of delegation listed in the chapter? Select all that apply.",opts:["Right task","Right circumstances","Right person","Right directions and communication","Right supervision and evaluation","Right documentation"],key:[0,1,2,3,4],rat:"ANA/NCSBN: right task, right circumstances, right person, right directions and communication, right supervision and evaluation.",why:{"5":"Documentation is one of the rights of medication administration, not delegation."},aid:"T-C-P-D-S: Task, Circumstance, Person, Direction, Supervision.",principle:"Don't mix delegation rights with medication rights.",takeaway:"Supervision and evaluation complete delegation.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 210"},
 {id:"L11",subj:"Leadership & Communication",topic:"Data versus judgment",cn:"Coordinated Care",fmt:"mc",diff:"A",ask:"Scope",comp:"scope",stem:"A nursing assistant reports that a resident says the arm with the IV feels cold, so the assistant brought another blanket. What is the LP/LV charge nurse's best action?",opts:["Assess the IV site personally for infiltration","Thank the assistant; the blanket solves the problem","Ask the assistant to recheck in an hour","Increase the room temperature"],key:0,rat:"Assistants gather data but lack the education to interpret it; the chapter uses this example — the infusion may have come out of the vein. Nursing judgment cannot be delegated.",why:{"1":"Misses possible infiltration.","2":"Delegates interpretation.","3":"Treats the symptom, not the cause."},aid:"They collect; you interpret.",principle:"Interpretation is a licensed-nurse function.",takeaway:"Follow up personally on any finding that may signal a change.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 209"},
 {id:"L12",subj:"Leadership & Communication",topic:"Delegation and policy",cn:"Coordinated Care",fmt:"mc",diff:"I",ask:"Scope",comp:"scope",stem:"An LVN's state NPA allows LVN charge nurses to delegate. What else must be true before the LVN delegates at work?",opts:["The facility's written policies must also permit it","The nursing assistant must have worked there one year","The physician must sign each delegation","Nothing else is needed"],key:0,rat:"The chapter states the facility must also give permission in its written policies; check facility policy.",why:{"1":"Not stated.","2":"Not stated.","3":"Policy is also required."},aid:"Law + policy + competence.",principle:"Scope depends on state law and facility policy.",takeaway:"Always check facility policy.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 203"},
 {id:"L13",subj:"Leadership & Communication",topic:"Leadership styles",cn:"Coordinated Care",fmt:"mc",diff:"F",ask:"Interpret",comp:"cue",stem:"A charge nurse asks staff for input and encourages them to problem-solve while still enforcing policies. Which style is this?",opts:["Democratic","Autocratic","Laissez-faire","Transactional only"],key:0,rat:"Box 17.1: democratic leaders share responsibility, seek input, encourage problem solving, and enforce policies with concern for employees.",why:{"1":"Autocratic leaders don't seek input.","2":"Laissez-faire leaders give away responsibility and try to please everyone.","3":"Not described here."},aid:"Autocratic tells, democratic asks, laissez-faire lets go.",principle:"Match behavior to definition.",takeaway:"Autocratic can be useful in emergencies.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 141"},
 {id:"L14",subj:"Leadership & Communication",topic:"Hospice versus palliative care",cn:"Coordinated Care",fmt:"mc",diff:"I",ask:"Teach",comp:"teach",stem:"A client newly diagnosed with heart failure asks about palliative care. Which statement by the nurse is accurate?",opts:["'Palliative care can start at diagnosis, and you can still choose life-saving treatment.'","'Palliative care is only for the last 6 months of life.'","'You must stop all treatment to get palliative care.'","'Palliative care is the same as hospice.'"],key:0,rat:"Hospice is for those certified as terminally ill with a focus on comfort as death approaches. Palliative care can begin at the onset of treatment, at any stage, while the client still chooses life-saving interventions.",why:{"1":"Describes hospice eligibility.","2":"Incorrect.","3":"They differ."},aid:"Palliative = comfort any time. Hospice = comfort at the end.",principle:"Distinguish similar services by eligibility.",takeaway:"Palliative care doesn't require giving up treatment.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF pp. 122–123"},
 {id:"L15",subj:"Leadership & Communication",topic:"Handoff report",cn:"Coordinated Care",fmt:"mc",diff:"F",ask:"Clarify",comp:"scope",stem:"Which element is required for a standardized change-of-shift (handoff) report under National Client Safety Goals?",opts:["An opportunity to ask and respond to questions","A taped report only","A report given only by the RN","A written note left at the station"],key:0,rat:"TJC National Client Safety Goals require a standardized handoff approach that includes an opportunity to ask and respond to questions.",why:{"1":"Report may be taped or oral per policy.","2":"Not required.","3":"Doesn't allow questions."},aid:"Handoff = hand + talk back.",principle:"Two-way communication prevents errors.",takeaway:"Clarify unclear information at report.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 211"},
 {id:"L16",subj:"Leadership & Communication",topic:"Liability in delegation",cn:"Coordinated Care",fmt:"mc",diff:"A",ask:"Scope",comp:"scope",stem:"An LVN properly delegated a duty to a competent nursing assistant, gave clear directions, and monitored. The resident was injured anyway. According to the chapter, who is liable?",opts:["The nursing assistant is also liable","Only the LVN","Only the facility","No one"],key:0,rat:"If the LVN delegated properly, including monitoring, and the client was injured, the nursing assistant is also liable. If the LVN delegated improperly, the LVN is liable.",why:{"1":"Proper delegation shares liability.","2":"Not stated.","3":"Incorrect."},aid:"Delegate right → share liability.",principle:"Accountability follows the quality of delegation.",takeaway:"Document directions and monitoring.",src:"Nursing_Combined_Chapters_8_9_14_15_17_Combined.pdf",pg:"PDF p. 210"}
];
